// Client-side filtering for the question tables generated by hooks/questions.py.
// Each filter group is a row of chip buttons (one active choice per group) and there is a
// text search over the title; the result counter is updated on every change.
document.addEventListener("DOMContentLoaded", () => {
  document.querySelectorAll(".question-filter").forEach((filterBox) => {
    const wrap = filterBox.nextElementSibling;          // .questions-wrap
    const table = wrap && wrap.querySelector("table");
    if (!table) return;
    const counter = wrap.nextElementSibling;
    const rows = Array.from(table.querySelectorAll("tbody tr"));
    const groups = Array.from(filterBox.querySelectorAll(".filter-group"));
    const search = filterBox.querySelector("input[data-filter='text']");

    const apply = () => {
      const f = {};
      groups.forEach((g) => (f[g.dataset.filter] = g.dataset.value));
      const text = search ? search.value.trim().toLowerCase() : "";
      let shown = 0;
      rows.forEach((row) => {
        const ok =
          (!f.level || row.dataset.level === f.level) &&
          (!f.difficulty || row.dataset.difficulty === f.difficulty) &&
          (!f.tag || row.dataset.tags.split(" ").includes(f.tag)) &&
          (!text || row.textContent.toLowerCase().includes(text));
        row.hidden = !ok;
        if (ok) shown++;
      });
      if (counter) counter.textContent = `מוצגות ${shown} מתוך ${rows.length} שאלות`;
    };

    groups.forEach((g) => {
      g.addEventListener("click", (e) => {
        const chip = e.target.closest(".filter-chip");
        if (!chip) return;
        g.querySelectorAll(".filter-chip").forEach((c) => c.classList.toggle("is-active", c === chip));
        g.dataset.value = chip.dataset.value;
        apply();
      });
    });
    if (search) search.addEventListener("input", apply);
    apply();
  });
});
